import test from 'node:test';
import assert from 'node:assert/strict';
import { canonical, overlaps } from '../src/paths.mjs';

test('canonical normalizes POSIX dot segments', () => {
  assert.equal(canonical('/a/b/../c'), '/a/c');
  assert.equal(canonical('/a/./b'), '/a/b');
});

test('canonical strips trailing separators on POSIX', () => {
  assert.equal(canonical('/a/b/'), '/a/b');
  assert.equal(canonical('/a/b///'), '/a/b');
});

test('overlaps returns true for equal paths', () => {
  assert.equal(overlaps('/a/b', '/a/b'), true);
});

test('overlaps detects nested path in both directions', () => {
  assert.equal(overlaps('/a', '/a/b/c'), true);
  assert.equal(overlaps('/a/b/c', '/a'), true);
});

test('overlaps rejects sibling prefix false positives', () => {
  assert.equal(overlaps('/a/b', '/a/bc'), false);
  assert.equal(overlaps('/a/bc', '/a/b'), false);
});

test('overlaps handles trailing separators', () => {
  assert.equal(overlaps('/a/', '/a/b'), true);
  assert.equal(overlaps('/a/b', '/a/'), true);
  assert.equal(overlaps('/a/b/', '/a/b//'), true);
});

test('canonical lowercases and normalizes backslashes on Windows', () => {
  assert.equal(canonical('C:\\A\\B\\..\\C', true), 'c:\\a\\c');
  assert.equal(canonical('C:/A/B/', true), 'c:\\a\\b');
