import { test } from 'node:test';
import assert from 'node:assert/strict';
import { canonical, overlaps } from '../src/paths.mjs';

test('canonical POSIX normalizes dot and double-dot segments', () => {
  assert.equal(canonical('/a/b/../c/./d'), '/a/c/d');
});

test('canonical POSIX strips trailing separators', () => {
  assert.equal(canonical('/a/b/'), '/a/b');
  assert.equal(canonical('/a/b//'), '/a/b');
});

test('overlaps returns true for equal paths', () => {
  assert.equal(overlaps('/var/log', '/var/log'), true);
});

test('overlaps detects nested paths in both directions', () => {
  assert.equal(overlaps('/var/log', '/var/log/app'), true);
  assert.equal(overlaps('/var/log/app', '/var/log'), true);
});

test('overlaps rejects sibling directories with shared prefix', () => {
  assert.equal(overlaps('/var/log', '/var/logs/app'), false);
  assert.equal(overlaps('/var/logx', '/var/log'), false);
});

test('overlaps requires separator boundary not just string prefix', () => {
  assert.equal(overlaps('/a/bc', '/a/b'), false);
  assert.equal(overlaps('/a/b', '/a/bc'), false);
});

test('overlaps handles trailing separators in inputs', () => {
  assert.equal(overlaps('/var/log/', '/var/log/app/'), true);
  assert.equal(overlaps('/var/log/', '/var/log'), true);
});

test('canonical Windows lowercases and normalizes slashes', () => {
  assert.equal(canonical('C:\\Users\\Sandy\\Docs', true), 'c:\\users\\sandy\\docs');
  assert.equal(canonical('C:/Users/Sandy/Docs', true), 'c:\\users\\sandy\\docs');
  assert.equal(canonical('C:/Users\\Sandy/', true), 'c:\\users\\sandy');
});

test('overlaps on Windows is case-insensitive and mixes slashes', () => {
  assert.equal(overlaps('C:\\Users\\Sandy', 'c:/users/sandy/file.txt', true), true);
  assert.equal(overlaps('C:/USERS', 'c:\\users\\app', true), true);
});

test('overlaps on Windows still rejects sibling prefix paths', () => {
  assert.equal(overlaps('C:\\data', 'C:\\database', true), false);
});

