-export async function withRetry(operation,options={}){throw new Error('not implemented');}
+export async function withRetry(operation, options = {}) {
+  const {
+    maxAttempts = 3,
+    baseDelayMs = 10,
+    maxDelayMs = 1000,
+    sleep = (ms) => new Promise((r) => setTimeout(r, ms)),
+    shouldRetry = () => true,
+    onAttempt = () => {},
+  } = options;
+
+  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) {
+    throw new TypeError('maxAttempts must be a positive integer');
+  }
+  if (!Number.isFinite(baseDelayMs) || baseDelayMs < 0) {
+    throw new TypeError('baseDelayMs must be a finite nonnegative number');
+  }
+  if (!Number.isFinite(maxDelayMs) || maxDelayMs < 0) {
+    throw new TypeError('maxDelayMs must be a finite nonnegative number');
+  }
+
+  let lastError;
+  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
+    onAttempt(attempt);
+    try {
+      return await operation(attempt);
+    } catch (error) {
+      lastError = error;
+      if (attempt === maxAttempts || !shouldRetry(error, attempt)) {
+        throw error;
+      }
+      await sleep(Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1)));
+    }
+  }
+  throw lastError;
+}

